static int gcdInt(int a, int b) {
  if (a < 0) a = -a;
  if (b < 0) b = -b;
  while (b != 0) {
    int t = a % b;
    a = b;
    b = t;
  }
  return a;
}

static int cmpSlope(const void *a, const void *b) {
  const int *x = (const int *)a;
  const int *y = (const int *)b;
  if (x[0] != y[0]) return x[0] - y[0];
  return x[1] - y[1];
}

int maxPoints(int **points, int pointsSize, int *pointsColSize) {
  (void)pointsColSize;
  if (pointsSize < 3) return pointsSize;

  int (*slopes)[2] = (int (*)[2])malloc(sizeof(int[2]) * (pointsSize - 1));
  int best = 1;

  for (int i = 0; i < pointsSize; i++) {
    int idx = 0;
    for (int j = i + 1; j < pointsSize; j++) {
      int dy = points[j][1] - points[i][1];
      int dx = points[j][0] - points[i][0];
      int g = gcdInt(dy, dx);
      if (g == 0) g = 1;
      dy /= g;
      dx /= g;
      if (dx < 0 || (dx == 0 && dy < 0)) {
        dy = -dy;
        dx = -dx;
      }
      slopes[idx][0] = dy;
      slopes[idx][1] = dx;
      idx++;
    }

    qsort(slopes, idx, sizeof(int[2]), cmpSlope);

    int run = 0;
    for (int k = 0; k < idx; k++) {
      if (k > 0 && slopes[k][0] == slopes[k - 1][0] && slopes[k][1] == slopes[k - 1][1]) {
        run++;
      } else {
        run = 1;
      }
      if (run + 1 > best) best = run + 1;
    }
  }

  free(slopes);
  return best;
}

class Solution {
public:
  int maxPoints(vector<vector<int>> &points) {
    int n = points.size();
    if (n < 3) return n;

    int best = 1;
    for (int i = 0; i < n; i++) {
      map<pair<int, int>, int> cnt;
      for (int j = i + 1; j < n; j++) {
        int dy = points[j][1] - points[i][1];
        int dx = points[j][0] - points[i][0];
        int g = gcd(dy, dx);
        if (g == 0) g = 1;
        dy /= g;
        dx /= g;
        if (dx < 0 || (dx == 0 && dy < 0)) {
          dy = -dy;
          dx = -dx;
        }
        int c = ++cnt[{dy, dx}];
        best = max(best, c + 1);
      }
    }
    return best;
  }
};

func gcd(a, b int) int {
	if a < 0 {
		a = -a
	}
	if b < 0 {
		b = -b
	}
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

