	if n < 3 {
		return n
	}

	best := 1
	for i := 0; i < n; i++ {
		cnt := make(map[[2]int]int)
		for j := i + 1; j < n; j++ {
			dy := points[j][1] - points[i][1]
			dx := points[j][0] - points[i][0]
			g := gcd(dy, dx)
			if g == 0 {
				g = 1
			}
			dy /= g
			dx /= g
			if dx < 0 || (dx == 0 && dy < 0) {
				dy, dx = -dy, -dx
			}
			key := [2]int{dy, dx}
			cnt[key]++
			if cnt[key]+1 > best {
				best = cnt[key] + 1
			}
		}
	}
